// Einstellungen (hier ändern)
const MODELL = 'claude-sonnet-5-5';
const MAX_TOKENS = 2000;
// Nur zum Testen: Steht hier ein Text, ersetzt er den Prompt aus der Plattform. Maßgeblich bleibt der Prompt im Repo
// (SYSTEM_PROMPT in supabase/functions/analyse-erstellen/analyse.ts). Danach wieder leer lassen.
const SYSTEM_UEBERSCHREIBEN = '';

const b = $input.first().json.body ?? {};
const fehler = [];
if (typeof b.nachricht !== 'string' || !b.nachricht.trim()) fehler.push('nachricht fehlt');
else if (b.nachricht.length > 60000) fehler.push('nachricht ist zu lang');
if (!SYSTEM_UEBERSCHREIBEN && (typeof b.system !== 'string' || !b.system.trim())) fehler.push('system fehlt');
if (!b.eingabe || typeof b.eingabe !== 'object' || Array.isArray(b.eingabe)) fehler.push('eingabe fehlt');

return [{
  json: {
    gueltig: fehler.length === 0,
    fehler,
    modell: MODELL,
    max_tokens: MAX_TOKENS,
    prompt_version: b.prompt_version ?? null,
    system: SYSTEM_UEBERSCHREIBEN || b.system,
    nachricht: b.nachricht,
    eingabe: b.eingabe,
  },
}];

// Liest die Antwort von Anthropic und macht daraus die Antwort an die Plattform: { ausgabe, meta }.
const r = $input.first().json;
const anfrage = $('Anfrage prüfen').first().json;
const fertig = (code, body) => [{ json: { code, body } }];

// Der Aufruf ist gescheitert (Zeitüberschreitung, keine Verbindung)
if (r.error || r.statusCode === undefined) {
  const detail = typeof r.error === 'string' ? r.error : (r.error?.message ?? 'Keine Verbindung zu Anthropic.');
  return fertig(502, { fehler: 'Die KI ist nicht erreichbar.', detail });
}

const status = Number(r.statusCode);
const k = r.body ?? {};
const detail = k?.error?.message ?? null;
if (status === 429) return fertig(429, { fehler: 'Die KI ist gerade ausgelastet.', detail });
if (status >= 400) return fertig(502, { fehler: 'Anthropic hat die Anfrage abgelehnt (Status ' + status + ').', detail });

const text = (k.content ?? []).filter((x) => x.type === 'text' && typeof x.text === 'string').map((x) => x.text).join('');
if (!text.trim()) return fertig(502, { fehler: 'Anthropic hat keinen Text geliefert.', detail: k.stop_reason ?? null });

// Wie die Edge Function: Code-Zaun entfernen, sonst das erste vollständige {...} suchen
function ersteJsonStelle(t) {
  const ohneZaun = t.replace(/```(?:json)?/gi, '');
  try {
    return JSON.parse(ohneZaun.trim());
  } catch (e) {
    // weiter
  }
  const start = ohneZaun.indexOf('{');
  if (start < 0) throw new Error('kein JSON');
  let tiefe = 0;
  let inText = false;
  let escape = false;
  for (let i = start; i < ohneZaun.length; i++) {
    const c = ohneZaun[i];
    if (inText) {
      if (escape) escape = false;
      else if (c === '\\') escape = true;
      else if (c === '"') inText = false;
    } else if (c === '"') inText = true;
    else if (c === '{') tiefe++;
    else if (c === '}' && --tiefe === 0) return JSON.parse(ohneZaun.slice(start, i + 1));
  }
  throw new Error('JSON unvollständig');
}

const hinweise = [];
if (k.stop_reason === 'max_tokens') hinweise.push('Die Antwort wurde abgeschnitten (max_tokens). MAX_TOKENS in „Anfrage prüfen“ erhöhen.');

let ausgabe;
try {
  ausgabe = ersteJsonStelle(text);
} catch (e) {
  // Die Plattform fragt dann selbst noch einmal nach (höchstens dreimal)
  hinweise.push('Die Antwort ist kein gültiges JSON: ' + e.message);
  ausgabe = text;
}

// Form prüfen (nur zur Orientierung; die Plattform prüft die Form beim Lesen selbst)
if (typeof ausgabe === 'object' && ausgabe !== null && !Array.isArray(ausgabe)) {
  if (typeof ausgabe.zusammenfassung !== 'string' || !ausgabe.zusammenfassung.trim()) hinweise.push('zusammenfassung fehlt');
  const erwartet = { staerken: [2, 4], entwicklungsfelder: [2, 4], gespraechsfragen: [3, 4], vereinbarungen_vorschlaege: [2, 3] };
  for (const [name, [min, max]] of Object.entries(erwartet)) {
    const liste = ausgabe[name];
    if (!Array.isArray(liste) || liste.length === 0) hinweise.push(name + ' fehlt oder ist leer');
    else if (liste.length < min || liste.length > max) hinweise.push(name + ': ' + liste.length + ' Punkte (erwartet ' + min + ' bis ' + max + ')');
  }
  if (!('kommentar_qualitaet_hinweis' in ausgabe)) hinweise.push('kommentar_qualitaet_hinweis fehlt (wird als leer gewertet)');
  if (/\bKollege\s+[A-Z]\b/.test(JSON.stringify(ausgabe))) hinweise.push('Enthält eine Buchstaben-Bezeichnung wie „Kollege A“ (laut Prompt nicht erlaubt)');
} else if (typeof ausgabe === 'object') {
  hinweise.push('Die Antwort ist kein JSON-Objekt');
}

return fertig(200, {
  ausgabe,
  meta: {
    modell: k.model ?? anfrage.modell,
    prompt_version: anfrage.prompt_version,
    stop_reason: k.stop_reason ?? null,
    tokens: { eingabe: k.usage?.input_tokens ?? null, ausgabe: k.usage?.output_tokens ?? null },
    hinweise,
  },
});

// Zahlencheck zur Orientierung: Jede Zahl im Text muss in den Daten vorkommen (1 bis 5 sind immer erlaubt).
// Maßgeblich ist der Faktencheck der Datenbank; er läuft beim Speichern in der Plattform. Hier sieht man es schon beim Testen.
const item = $input.first().json;
if (item.code !== 200 || typeof item.body.ausgabe !== 'object' || item.body.ausgabe === null) return [{ json: item }];

const eingabe = $('Anfrage prüfen').first().json.eingabe;

function zahlenAus(text, ohneListennummern) {
  let t = String(text);
  if (ohneListennummern) t = t.replace(/^\s*\d+[.)]\s+/gm, '');
  return (t.match(/\d+(?:[.,]\d+)?/g) ?? []).map((x) => Math.abs(parseFloat(x.replace(',', '.'))));
}

function sammle(wert, ziel) {
  if (typeof wert === 'number') ziel.push(Math.abs(wert));
  else if (typeof wert === 'string') ziel.push(...zahlenAus(wert, false));
  else if (Array.isArray(wert)) wert.forEach((x) => sammle(x, ziel));
  else if (wert && typeof wert === 'object') Object.values(wert).forEach((x) => sammle(x, ziel));
}

const erlaubt = [1, 2, 3, 4, 5];
sammle(eingabe, erlaubt);

const texte = [];
(function texteSammeln(w) {
  if (typeof w === 'string') texte.push(w);
  else if (Array.isArray(w)) w.forEach(texteSammeln);
  else if (w && typeof w === 'object') Object.values(w).forEach(texteSammeln);
})(item.body.ausgabe);

const fehlend = [];
for (const z of texte.flatMap((t) => zahlenAus(t, true))) {
  if (!erlaubt.some((e) => Math.abs(e - z) < 1e-9)) {
    const anzeige = String(z).replace('.', ',');
    if (!fehlend.includes(anzeige)) fehlend.push(anzeige);
  }
}

item.body.meta.zahlen_nicht_in_daten = fehlend;
item.body.meta.faktencheck_orientierung = fehlend.length === 0 ? 'bestanden' : 'Abweichung';
return [{ json: item }];
